@php
$money=fn($v)=>number_format((float)($v ?? 0),2,',','.');
$money3=fn($v)=>number_format((float)($v ?? 0),3,',','.');
$digits=fn($v)=>preg_replace('/\D+/', '', (string)$v);
$doc=function($v) use($digits){$n=$digits($v);if(strlen($n)===14)return substr($n,0,2).'.'.substr($n,2,3).'.'.substr($n,5,3).'/'.substr($n,8,4).'-'.substr($n,12,2);if(strlen($n)===11)return substr($n,0,3).'.'.substr($n,3,3).'.'.substr($n,6,3).'-'.substr($n,9,2);return $v;};
$cep=function($v) use($digits){$n=$digits($v);return strlen($n)===8?substr($n,0,5).'-'.substr($n,5):$v;};
$logoDataUri=$danfeLogoDataUri ?? $nfe->empresa?->logo_data_uri;
$tributos=$danfeTributos ?? [];
$totalFederal=(float)($tributos['federais'] ?? 0);
$totalEstadual=(float)($tributos['estaduais'] ?? 0);
$totalMunicipal=(float)($tributos['municipais'] ?? 0);
$totalTributos=(float)($tributos['total'] ?? ($totalFederal+$totalEstadual+$totalMunicipal));
$percentFederal=(float)($tributos['percentual_federal'] ?? 0);
$percentEstadual=(float)($tributos['percentual_estadual'] ?? 0);
$percentMunicipal=(float)($tributos['percentual_municipal'] ?? 0);
$percentTotal=(float)($tributos['percentual_total'] ?? 0);
$fonteTributos=(string)($tributos['fonte'] ?? 'IBPT / XML fiscal');
@endphp

